source.css:
.stage { position: absolute; inset: 0; background: #0f1020; color: #f4f1ea; font-family: inter, sans-serif;
  --arrive: cubic-bezier(0.16, 1, 0.3, 1); }
.scene { position: absolute; inset: 0; }
.in { position: absolute; inset: 0; }
.logo { position: absolute; left: 720px; top: 300px; width: 480px; height: 160px;
  animation: logo-in 0.9s var(--arrive) -0.15s both; }
.hero { position: absolute; left: 160px; top: 560px; width: 1600px; margin: 0; text-align: center;
  font-size: 172px; font-weight: 900; line-height: 1.05; letter-spacing: -0.02em;
  animation: rise 0.7s var(--arrive) 0.5s both; }
.s1 { animation: scene-out 0.4s ease-in 3s both; }
.s2 .in { animation: scene-in 0.4s ease-out 3s both; }
.badge { position: absolute; left: 840px; top: 250px; width: 240px; height: 240px;
  animation: badge-in 0.9s var(--arrive) 3.1s both; }
.sub { position: absolute; left: 160px; top: 600px; width: 1600px; margin: 0; text-align: center;
  font-size: 96px; font-weight: 700; line-height: 1.1;
  animation: rise 0.7s var(--arrive) 3.5s both; }
.chip { position: absolute; left: 1700px; top: 900px; width: 80px; height: 80px;
  background: url(../badge.svg) center / contain no-repeat;
  animation: fade-in 0.5s ease-out 4s both; }
@keyframes logo-in { from { opacity: 0; transform: translateY(40px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes rise { from { opacity: 0; transform: translateY(48px); } to { opacity: 1; transform: translateY(0); } }
@keyframes badge-in { from { opacity: 0; transform: rotate(-90deg) scale(0.6); } to { opacity: 1; transform: rotate(0deg) scale(1); } }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes scene-out { to { opacity: 0; } }
@keyframes scene-in { from { opacity: 0; } to { opacity: 1; } }
